// --- CONFIGURACIÓN DE SEGURIDAD ---
// Este es el ID único de tu grupo de comando privado.
const ID_GRUPO_COMANDO = '120363041361026474@g.us'; 

// Obtiene el remitente del mensaje (que en este caso es el grupo).
const remitente = $input.item.json.payload?.from || '';

// --- LÓGICA DE FILTRADO ---
// Compara si el ID del remitente coincide exactamente con el ID de tu grupo.
if (remitente !== ID_GRUPO_COMANDO) {
    // Si NO coincide, el mensaje viene de otro grupo o un cliente. Se ignora.
    console.log(`Mensaje ignorado de: ${remitente}. No es el grupo de comando.`);
    return null;
}

// Si el ID SÍ coincide, el mensaje es un comando válido.
console.log(`Comando recibido del grupo de operaciones: ${ID_GRUPO_COMANDO}`);

// Extraemos el texto del comando para que el agente lo pueda procesar.
$input.item.json.mensajeClienteActual = $input.item.json.payload?.body?.trim() || '';

// Dejamos pasar el item para que el agente lo procese.
return $input.item;

