// ============================================
// EXTRACTOR INTELIGENTE v2.0
// Extrae teléfono y nombre del comando
// ============================================
const prompt = $input.item.json.prompt ||
               $input.item.json.mensajeClienteActual ||
               $input.item.json.payload?.body || '';

console.log('Prompt recibido:', prompt);

// ============================================
// 1. EXTRACCIÓN DE TELÉFONO (Formato Colombiano)
// ============================================
// Normalizar: eliminar caracteres excepto dígitos
const normalizedPrompt = prompt.replace(/[^\d]/g, '');

// Regex para teléfonos colombianos:
// - 10 dígitos empezando con 3 (ej: 3161932558)
// - 12 dígitos empezando con 57 y luego 3 (ej: 573161932558)
const phoneRegex = /(?:57)?(3\d{9})/g;
const phoneMatches = normalizedPrompt.match(phoneRegex);
let telefono_objetivo = null;

if (phoneMatches && phoneMatches.length > 0) {
    // Tomar el primer teléfono válido encontrado
    telefono_objetivo = phoneMatches[0].replace(/^57/, ''); // Remover prefijo 57 si existe
    console.log('Teléfono extraído:', telefono_objetivo);
} else {
    console.log('No se encontró teléfono válido');
}

// ============================================
// 2. EXTRACCIÓN DE NOMBRE
// ============================================
let nombre_extraido = null;
// Patrones comunes para detectar nombres en comandos:
// "actualiza el nombre del cliente XXX a NOMBRE"
// "registra el nombre NOMBRE para el cliente XXX"
// "el nombre es NOMBRE y el fono es XXX"
// "cliente XXX se llama NOMBRE"
const patrones = [
    /(?:a|al nombre)\s+["']?([A-Za-zÁ-ÿ\s]+?)["']?(?:\s|$)/i,  // "a Consuelo", "al nombre María"
    /(?:nombre es|llama)\s+["']?([A-Za-zÁ-ÿ\s]+?)["']?(?:\s+y|\s*$)/i,  // "nombre es Juan", "se llama María"
    /registra(?:\s+el)?\s+nombre\s+["']?([A-Za-zÁ-ÿ\s]+?)["']?(?:\s+para|$)/i,  // "registra el nombre Pedro"
];

for (const patron of patrones) {
    const match = prompt.match(patron);
    if (match && match[1]) {
        nombre_extraido = match[1].trim();

        // Limpieza: eliminar palabras comunes que no son nombres
        const palabrasExcluir = ['del', 'cliente', 'el', 'la', 'un', 'una', 'para', 'de'];
        let palabrasNombre = nombre_extraido.split(/\s+/).filter(palabra => 
            !palabrasExcluir.includes(palabra.toLowerCase())
        );

        nombre_extraido = palabrasNombre.join(' ').trim();

        // Validación: el nombre debe tener al menos 2 caracteres y no puede ser solo números
        if (nombre_extraido.length >= 2 && !/^\d+$/.test(nombre_extraido)) {
            console.log('Nombre extraído:', nombre_extraido);
            break;
        } else {
            nombre_extraido = null;
        }
    }
}

if (!nombre_extraido) {
    console.log('No se pudo extraer nombre del comando');
}

// ============================================
// 3. SALIDA ESTRUCTURADA
// ============================================
$input.item.json.extraccion = {
    telefono_objetivo: telefono_objetivo,
    nombre_extraido: nombre_extraido,
    prompt_original: prompt,
    extraccion_exitosa: !!(telefono_objetivo || nombre_extraido)
};

// Mantener compatibilidad con nodos existentes
$input.item.json.telefono_objetivo = telefono_objetivo;
$input.item.json.nombre_extraido = nombre_extraido;

// --- CORRECCIÓN ---
// Devolver el item dentro de un array para cumplir con el formato de n8n
return [$input.item];

